def format_iso(dt: datetime) -> str:
    return dt.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def parse_iso(dt_str: str) -> datetime:
    return datetime.fromisoformat(dt_str.replace("Z", "+00:00"))

def parse_iso_ts(dt_str: str) -> float:
    return parse_iso(dt_str).timestamp()

def get_now(request: Request) -> datetime:
    clock_header = request.headers.get("X-Test-Clock")
    if not clock_header:
        return datetime.now(timezone.utc)
    try:
        return parse_iso(clock_header)
    except ValueError:
        raise HTTPException(status_code=400, detail={"error": {"code": "invalid_date", "message": "Invalid X-Test-Clock format"}})

def round_0_dec(val: float) -> int:
    return int(Decimal(str(val)).quantize(Decimal("1"), rounding=ROUND_HALF_UP))

def round_6_dec(val: Optional[float]) -> Optional[float]:
    if val is None:
        return None
    return float(Decimal(str(val)).quantize(Decimal("0.000000"), rounding=ROUND_HALF_UP))

def get_median(values: List[float]) -> Optional[int]:
    if not values:
        return None
    s = sorted(values)
    n = len(s)
    if n % 2 == 1:
        mid = s[n // 2]
    else:
        mid = (s[n // 2 - 1] + s[n // 2]) / 2.0
    return round_0_dec(mid)

