@app.post("/tickets/{ticket_id}/{action}")
async def transition_ticket(ticket_id: str, action: str, request: Request):
    if ticket_id not in tickets_db:
        raise HTTPException(status_code=404, detail={"error": {"code": "not_found", "message": "Ticket not found"}})
    ticket = tickets_db[ticket_id]
    now = get_now(request)
    if action == "ack" and ticket["state"] == "new":
        ticket["state"] = "acknowledged"
        ticket["acknowledged_at"] = format_iso(now)
    elif action == "start" and ticket["state"] == "acknowledged":
        ticket["state"] = "in_progress"
    elif action == "resolve" and ticket["state"] == "in_progress":
        ticket["state"] = "resolved"
        ticket["resolved_at"] = format_iso(now)
    elif action == "close" and ticket["state"] == "resolved":
        ticket["state"] = "closed"
        ticket["closed_at"] = format_iso(now)
    elif action == "reopen" and ticket["state"] in ["resolved", "closed"]:
        check_time = parse_iso(ticket["resolved_at"]) if ticket["resolved_at"] else parse_iso(ticket["closed_at"])
        if (now - check_time).days < 7:
            ticket["state"] = "in_progress"
            ticket["resolved_at"] = None
            ticket["closed_at"] = None
        else:
            raise HTTPException(status_code=409, detail={"error": {"code": "reopen_expired", "message": "Reopen window expired"}})
    else:
        raise HTTPException(status_code=409, detail={"error": {"code": "illegal_transition", "message": "Illegal state transition"}})
    tickets_db[ticket_id] = ticket
    return ticket

@app.get("/tickets/{ticket_id}/sla")
async def get_ticket_sla(ticket_id: str, request: Request):
    if ticket_id not in tickets_db:
        raise HTTPException(status_code=404, detail={"error": {"code": "not_found", "message": "Ticket not found"}})
    ticket = tickets_db[ticket_id]
    now = get_now(request)
    ack_due = parse_iso(ticket["sla"]["ack_due_at"])
    res_due = parse_iso(ticket["sla"]["resolve_due_at"])
    ack_breached = (now > ack_due) and (ticket["acknowledged_at"] is None or parse_iso(ticket["acknowledged_at"]) > ack_due)
    resolve_breached = (now > res_due) and (ticket["resolved_at"] is None or parse_iso(ticket["resolved_at"]) > res_due)
    paused = False
    if ticket["priority"] != "P1" and ticket["state"] not in ["resolved", "closed"]:
        now_warsaw = now.astimezone(WARSAW_TZ)
        if now_warsaw.weekday() >= 5 or not (8 <= now_warsaw.hour < 16):
            paused = True
    return {"ack_breached": ack_breached, "resolve_breached": resolve_breached, "paused": paused}

