@app.get("/kb/search")
async def kb_search(q: Optional[str] = None):
    if not q or len(q) > 200:
        return JSONResponse(
            status_code=400,
            content={"error": {"code": "bad_request", "message": "Invalid q parameter"}}
        )
    try:
        async with httpx.AsyncClient(timeout=2.0) as client:
            resp = await client.get(f"{KB_INDEX_URL}/search", params={"q": q})
            resp.raise_for_status()
            return resp.json()
    except Exception:
        return JSONResponse(
            status_code=502,
            content={"error": {"code": "upstream_unavailable", "message": "Upstream service failed or timed out"}}
        )
